-- create_db_schema.sql

-- Track the master project or session state
CREATE TABLE agent_workflows (
    workflow_id SERIAL PRIMARY KEY,
    user_requirement TEXT NOT NULL,
    current_status VARCHAR(50) DEFAULT 'idle', -- e.g., 'analyzing', 'coding', 'reviewing', 'completed'
    current_task_index INT DEFAULT 0,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Store the checklist of sequential sub-tasks generated by the Supervisor
CREATE TABLE agent_tasks (
    task_id SERIAL PRIMARY KEY,
    workflow_id INT REFERENCES agent_workflows(workflow_id) ON DELETE CASCADE,
    step_number INT NOT NULL,
    domain VARCHAR(50) NOT NULL,
    task_description TEXT NOT NULL,
    files_affected TEXT[] NOT NULL,
    status VARCHAR(50) DEFAULT 'pending' -- 'pending', 'in_progress', 'completed', 'failed'
);

-- Store technical specifications for coding tasks
CREATE TABLE agent_specs (
    spec_id SERIAL PRIMARY KEY,
    workflow_id INT REFERENCES agent_workflows(workflow_id) ON DELETE CASCADE,
    task_id INT REFERENCES agent_tasks(task_id) ON DELETE CASCADE,
    technical_spec TEXT NOT NULL
);

-- Store generated code for coding tasks
CREATE TABLE agent_code (
    code_id SERIAL PRIMARY KEY,
    task_id INT REFERENCES agent_tasks(task_id) ON DELETE CASCADE,
    target_file_path VARCHAR(512) NOT NULL,
    generated_code TEXT NOT NULL,
    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP
);

-- Store compiler/quality feedback for code
CREATE TABLE agent_reviews (
    review_id SERIAL PRIMARY KEY,
    code_id INT REFERENCES agent_code(code_id) ON DELETE CASCADE,
    compilation_status VARCHAR(50) DEFAULT 'pending' -- 'pending', 'success', 'failure'
);













CREATE TABLE app_context_projects (
    context_project_id SERIAL PRIMARY KEY,

    project_name VARCHAR(255) NOT NULL,

    root_path TEXT NOT NULL,

    description TEXT,

    detected_stack JSONB DEFAULT '{}'::jsonb,

    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    UNIQUE(root_path)
);


CREATE TABLE app_context_files (
    context_file_id SERIAL PRIMARY KEY,

    context_project_id INT NOT NULL
        REFERENCES app_context_projects(context_project_id)
        ON DELETE CASCADE,

    file_path TEXT NOT NULL,

    relative_path TEXT NOT NULL,

    file_name VARCHAR(512) NOT NULL,

    extension VARCHAR(50),

    language VARCHAR(100),

    framework VARCHAR(100),

    file_type VARCHAR(100),
    -- source, schema, config, test, documentation, asset, etc.

    size_bytes BIGINT,

    content_hash VARCHAR(128),

    is_binary BOOLEAN NOT NULL DEFAULT FALSE,

    is_generated BOOLEAN NOT NULL DEFAULT FALSE,

    is_active BOOLEAN NOT NULL DEFAULT TRUE,

    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,
    updated_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    UNIQUE(context_project_id, relative_path)
);


CREATE TABLE app_context_chunks (
    context_chunk_id BIGSERIAL PRIMARY KEY,

    context_file_id INT NOT NULL
        REFERENCES app_context_files(context_file_id)
        ON DELETE CASCADE,

    chunk_index INT NOT NULL,

    start_line INT,

    end_line INT,

    content TEXT NOT NULL,

    content_hash VARCHAR(128),

    embedding vector(1536),

    metadata JSONB DEFAULT '{}'::jsonb,

    created_at TIMESTAMP DEFAULT CURRENT_TIMESTAMP,

    UNIQUE(context_file_id, chunk_index)
);


CREATE TABLE app_context_symbols (
    symbol_id BIGSERIAL PRIMARY KEY,

    context_file_id INT NOT NULL
        REFERENCES app_context_files(context_file_id)
        ON DELETE CASCADE,

    symbol_name VARCHAR(512) NOT NULL,

    symbol_type VARCHAR(100),
    -- class, function, method, table, route, component, interface, etc.

    start_line INT,

    end_line INT,

    signature TEXT,

    metadata JSONB DEFAULT '{}'::jsonb
);


CREATE TABLE app_context_dependencies (
    dependency_id BIGSERIAL PRIMARY KEY,

    context_project_id INT NOT NULL
        REFERENCES app_context_projects(context_project_id)
        ON DELETE CASCADE,

    source_file_id BIGINT
        REFERENCES app_context_files(context_file_id)
        ON DELETE CASCADE,

    target_file_id BIGINT
        REFERENCES app_context_files(context_file_id)
        ON DELETE CASCADE,

    dependency_type VARCHAR(100),
    -- import, require, include, extends, implements, reference, etc.

    dependency_name TEXT,

    metadata JSONB DEFAULT '{}'::jsonb
);




ALTER TABLE app_context_symbols
ADD COLUMN IF NOT EXISTS qualified_name TEXT,
ADD COLUMN IF NOT EXISTS parent_symbol_id BIGINT
    REFERENCES app_context_symbols(symbol_id)
    ON DELETE CASCADE,
ADD COLUMN IF NOT EXISTS signature_hash VARCHAR(128);



ALTER TABLE app_context_dependencies
ADD COLUMN IF NOT EXISTS source_symbol_id BIGINT
    REFERENCES app_context_symbols(symbol_id)
    ON DELETE CASCADE,
ADD COLUMN IF NOT EXISTS target_symbol_id BIGINT
    REFERENCES app_context_symbols(symbol_id)
    ON DELETE CASCADE;


ALTER TABLE app_context_chunks
ADD COLUMN IF NOT EXISTS primary_symbol_id BIGINT
    REFERENCES app_context_symbols(symbol_id)
    ON DELETE SET NULL;


ALTER TABLE app_context_symbols
ADD COLUMN IF NOT EXISTS signature TEXT;

ALTER TABLE app_context_dependencies
ADD COLUMN IF NOT EXISTS target_file_id BIGINT
    REFERENCES app_context_files(context_file_id)
    ON DELETE CASCADE;

ALTER TABLE app_context_dependencies
ADD COLUMN IF NOT EXISTS target_file_id BIGINT
    REFERENCES app_context_files(context_file_id)
    ON DELETE CASCADE;


-- ============================================================
-- APP CONTEXT SNAPSHOTS
-- ============================================================
-- Stores immutable indexing snapshots for a project.
--
-- A snapshot represents the state of the indexed repository at
-- a particular point in time.
-- ============================================================

CREATE TABLE IF NOT EXISTS app_context_snapshots (
    snapshot_id BIGSERIAL PRIMARY KEY,

    context_project_id INT NOT NULL
        REFERENCES app_context_projects(context_project_id)
        ON DELETE CASCADE,

    snapshot_hash VARCHAR(128) NOT NULL,

    file_count INT NOT NULL DEFAULT 0,

    created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP,

    CONSTRAINT uq_context_snapshot_project_hash
        UNIQUE (
            context_project_id,
            snapshot_hash
        )
);

ALTER TABLE agent_tasks
ADD COLUMN IF NOT EXISTS 
change_type VARCHAR(50) DEFAULT 'edit'


-- ============================================================
-- INDEXES
-- ============================================================

CREATE INDEX IF NOT EXISTS idx_context_snapshots_project
ON app_context_snapshots(context_project_id);

CREATE INDEX IF NOT EXISTS idx_context_snapshots_created
ON app_context_snapshots(created_at DESC);

CREATE INDEX IF NOT EXISTS idx_context_snapshots_project_created
ON app_context_snapshots(
    context_project_id,
    created_at DESC
);


